// Versie 1.4.2
// De archivering gebruikt uitsluitend oorspronkelijke Outlook message ID's
// uit Code-Bron herkennen. Verwerkte vacature-items bepalen alleen welke
// bronberichten mogen worden gearchiveerd.

let origineleEmails = [];
let verwerkteVacatures = [];

try {
  origineleEmails = $('Code-Bron herkennen').all();
} catch (e) {}

try {
  verwerkteVacatures = $('Code-JSON.parse').all();
} catch (e) {}

if (origineleEmails.length === 0 || verwerkteVacatures.length === 0) {
  return [];
}

const normaliseer = (waarde) => String(waarde ?? '').trim().toLowerCase();

const verwerkteIds = new Set();
const verwerkteOnderwerpen = new Set();
const verwerkteBrokerEmails = new Set();
const verwerkteBronCodes = new Set();

for (const item of verwerkteVacatures) {
  const j = item.json || {};

  const id = String(j.bronBerichtId ?? '').trim();
  const onderwerp = normaliseer(j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const broker = normaliseer(j.broker);

  if (id) verwerkteIds.add(id);
  if (onderwerp) verwerkteOnderwerpen.add(onderwerp);
  if (brokerEmail) verwerkteBrokerEmails.add(brokerEmail);

  if (broker.includes('liblab')) verwerkteBronCodes.add('liblab');
  if (broker.includes('circle8')) verwerkteBronCodes.add('circle8');
  if (
    broker.includes('staffinggroep') ||
    broker.includes('staffingteam')
  ) {
    verwerkteBronCodes.add('staffinggroep');
  }
  if (broker.includes('mipublic')) {
    verwerkteBronCodes.add('mipublic');
  }
  if (broker.includes('striive')) {
    verwerkteBronCodes.add('striive');
  }
  if (broker.includes('hero')) {
    verwerkteBronCodes.add('hero');
  }
  if (broker.includes('zzp-opdrachten') || broker.includes('zzp opdrachten')) {
    verwerkteBronCodes.add('zzp_opdrachten');
  }
  if (
    broker.includes('yacht') ||
    broker.includes('randstad professional')
  ) {
    verwerkteBronCodes.add('yacht');
  }
  if (broker.includes('bluetrail')) verwerkteBronCodes.add('bluetrail');
  if (broker.includes('publieke partner')) {
    verwerkteBronCodes.add('depubliekepartner');
  }
}

const uniekeEmails = new Map();

for (const item of origineleEmails) {
  const j = item.json || {};

  // DPP wordt vanaf v1.5.2 via een onafhankelijke archiveringsroute
  // afgehandeld, ook als er nul geldige vacatures zijn.
  if (normaliseer(j.bronCode) === 'depubliekepartner') {
    continue;
  }

  const origineelMessageId = String(j.id ?? '').trim();
  if (!origineelMessageId) continue;

  const onderwerp = normaliseer(j.subject ?? j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const bronCode = normaliseer(j.bronCode);

  const exactIdGevonden = verwerkteIds.has(origineelMessageId);
  const onderwerpGevonden =
    Boolean(onderwerp) && verwerkteOnderwerpen.has(onderwerp);
  const brokerEmailGevonden =
    Boolean(brokerEmail) && verwerkteBrokerEmails.has(brokerEmail);
  const bronGevonden =
    Boolean(bronCode) && verwerkteBronCodes.has(bronCode);

  const moetArchiveren =
    exactIdGevonden ||
    onderwerpGevonden ||
    (brokerEmailGevonden && bronGevonden);

  if (!moetArchiveren) continue;

  if (!uniekeEmails.has(origineelMessageId)) {
    uniekeEmails.set(origineelMessageId, {
      json: {
        bronBerichtId: origineelMessageId,
        origineelOutlookMessageId: origineelMessageId,
        internetMessageId: j.internetMessageId ?? '',
        conversationId: j.conversationId ?? '',
        bronBerichtOnderwerp: String(
          j.subject ?? j.bronBerichtOnderwerp ?? ''
