        brokerEmail: j.brokerEmail ?? '',
        bronCode: j.bronCode ?? '',
        emailOntvangenOp:
          j.receivedDateTime ??
          j.emailOntvangenOp ??
          j.sentDateTime ??
          '',
        archiveSelectieReden:
          exactIdGevonden
            ? 'exact_message_id'
            : onderwerpGevonden
              ? 'onderwerp'
              : 'broker_en_bron'
      }
    });
  }
}

return Array.from(uniekeEmails.values());

