function htmlNaarTekst(html = '') {
  return String(html)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&euro;/gi, '€');
}

function normaliseerTekst(tekst = '') {
  return String(tekst)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\u00a0/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function verwijderHandtekening(tekst = '') {
  const markers = [
    '\nMet vriendelijke groet',
    '\nKind regards',
    '\nRECRUITMENT & RESOURCING',
    '\nDisclaimer:'
  ];

  let eindPositie = tekst.length;

  for (const marker of markers) {
    const positie = tekst.toLowerCase().indexOf(marker.toLowerCase());

    if (positie !== -1 && positie < eindPositie) {
      eindPositie = positie;
    }
  }

  return tekst.slice(0, eindPositie).trim();
}

function zoekWaarde(tekst, patroon, groep = 1) {
  const resultaat = String(tekst).match(patroon);

  if (!resultaat) {
    return '';
  }

  return String(resultaat[groep] ?? '').trim();
}

function haalVacatureUrlUitHtml(html = '') {
  const vacatureLink = String(html).match(
    /<a[^>]+href=["']([^"']+)["'][^>]*>[\s\S]*?vacature op onze website[\s\S]*?<\/a>/i
  );

  if (vacatureLink?.[1]) {
    return vacatureLink[1]
      .replace(/&amp;/gi, '&')
      .trim();
  }

  return '';
}

