      .replace(/^Nieuwe opdracht\s*[-–—]\s*/i, '')
      .replace(/\s*\(VNR-\d+\)\s*/i, '')
      .trim();
  }

  const opdrachtgever = zoekWaarde(
    vacatureTekst,
    /Voor onze opdrachtgever\s+(.+?)\s+zijn we op zoek naar/i
  );

  const sluitingsdatum = zoekWaarde(
