  );

  const standplaats = zoekWaarde(
    vacatureTekst,
    /Standplaats\s*:\s*([^\n]+)/i
  );

  const schaal = zoekWaarde(
    vacatureTekst,
    /Schaal\s*:\s*([^\n]+)/i
  );

