function parse(html=''){
  const out=[];
  const rx=/<a[^>]+href=["'](https?:\\?\/\\?\/depubliekepartner\.nl\\?\/[^"']+)["'][^>]*>\s*<h2[^>]*class=["'][^"']*\bue_job_title\b[^"']*["'][^>]*>([\s\S]*?)<\/h2>/gi;
  let m;
  while((m=rx.exec(html))!==null){
    const url=String(m[1]).replace(/\\\//g,'/').replace(/^http:\/\//i,'https://').trim();
    const titel=decode(m[2]);
    if(url&&titel) out.push({url,titel});
  }
  return out;
}

