function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) =>
      String.fromCodePoint(parseInt(code, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&euro;/gi, '€');
}

function htmlNaarTekst(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(br|hr)\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|section|article|li|h1|h2|h3|h4|h5|h6|tr)>/gi, '\n')
      .replace(/<li\b[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function parseJsonLdJob(html) {
  const blocks =
    String(html).match(
      /<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi
    ) || [];

  for (const block of blocks) {
    const raw = block
      .replace(/<script[^>]*>/i, '')
      .replace(/<\/script>/i, '')
      .trim();

    let data;
    try {
      data = JSON.parse(raw);
    } catch (e) {
      continue;
    }

    const kandidaten = [];
    const voegToe = (waarde) => {
      if (!waarde) return;
      if (Array.isArray(waarde)) {
        waarde.forEach(voegToe);
        return;
      }
      if (typeof waarde !== 'object') return;
      kandidaten.push(waarde);
      if (Array.isArray(waarde['@graph'])) waarde['@graph'].forEach(voegToe);
    };
    voegToe(data);

    for (const kandidaat of kandidaten) {
      const type = kandidaat?.['@type'];
      if (
        type === 'JobPosting' ||
        (Array.isArray(type) && type.includes('JobPosting'))
      ) {
        return kandidaat;
      }
    }
  }

  return null;
}

function extractContentBlock(html) {
  const containers =
    String(html).match(
      /<div class="elementor-widget-container">([\s\S]*?)<\/div>/gi
    ) || [];

  const herkenningspunten =
    /Opdrachtomschrijving|Functieomschrijving|Eisen|Wensen|Taken|Aanvraagnummer|Contractvorm|Sluitingsdatum|Startdatum|Uren per week/i;

  const gezien = new Set();
  const teksten = [];

  for (const container of containers) {
    const inner = container
      .replace(/^<div class="elementor-widget-container">/i, '')
      .replace(/<\/div>$/i, '');

    const tekst = htmlNaarTekst(inner);
    if (!herkenningspunten.test(tekst)) continue;
    if (tekst.length < 40 || gezien.has(tekst)) continue;

    gezien.add(tekst);
    teksten.push(tekst);
  }

  return teksten.join('\n\n').trim();
}

function schoonTitel(value = '') {
  return String(value)
    .replace(/\s*\|.*$/, '')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, "'")
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

