function normaliseer(value = '') {
  return String(value).toLowerCase().trim().replace(/\s+/g, ' ');
}

function sleutelVoor(j) {
  const url = normaliseer(j.vacatureUrl).replace(/[?#].*$/, '').replace(/\/$/, '');
  if (url) return `url:${url}`;
  const titel = normaliseer(j.vacatureTitel);
  const broker = normaliseer(j.broker || j.brokerEmail);
  const tekst = normaliseer(j.vacatureTekst).slice(0, 500);
  return `fallback:${broker}|${titel}|${tekst}`;
}

const gezienInRun = new Set();
const output = [];
