  const sleutel = sleutelVoor(item.json);
  if (!sleutel || gezienInRun.has(sleutel) || store.verwerkteVacatures[sleutel]) continue;
  gezienInRun.add(sleutel);
  output.push({ json: { ...item.json, deduplicatieSleutel: sleutel }, pairedItem: item.pairedItem });
}

