const matchregels = Number(r.aantal_matchregels_totaal || 0);
const gearchiveerd = Number(r.aantal_gearchiveerde_emails || 0);
const dubbelen = Number(r.aantal_dubbele_overgeslagen || 0);

const waarschuwingen = [];

if (emails > 0 && vacaturesVoor === 0) {
  waarschuwingen.push('E-mails gelezen, maar geen vacatures uit bronnen gehaald.');
}
if (vacaturesVoor > 0 && vacatures === 0) {
  waarschuwingen.push('Vacatures gevonden, maar geen vacatures door validatie gekomen.');
}
if (vacatures > 0 && matchregels === 0) {
  waarschuwingen.push('Geldige vacatures gevonden, maar geen AI-matchregels geproduceerd.');
}
if (!r.testmodus && vacatures > 0 && gearchiveerd === 0) {
  waarschuwingen.push('Vacatures verwerkt, maar geen bronberichten gearchiveerd.');
