// BlueTrail v1.7.3
// Verwerkt de detacheringpagina en de paginering van /opdrachten/.
// Alleen URL's met Dienstverband Detachering of Interim worden gebruikt.
// Vacatures worden vóór detailverwerking voorgefilterd op alle gelijkwaardige
// keywords van actieve medewerkers. Dubbele zoekwoorden en vacature-URL's
// worden verwijderd.

function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, c) => String.fromCodePoint(Number(c)))
    .replace(/&#x([0-9a-f]+);/gi, (_, c) =>
      String.fromCodePoint(parseInt(c, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function stripHtml(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

function normaliseerTekst(value = '') {
  return stripHtml(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9+#./ -]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normaliseerUrl(url = '') {
  let resultaat = decodeHtml(url)
    .replace(/\\\//g, '/')
    .trim();

  if (resultaat.startsWith('//')) resultaat = `https:${resultaat}`;
  if (resultaat.startsWith('/')) {
    resultaat = `https://www.bluetrail.nl${resultaat}`;
  }

  return resultaat
    .split('#')[0]
    .split('?')[0]
    .trim();
}

function haalHtmlOp(json) {
  if (typeof json === 'string') return json;
  if (!json || typeof json !== 'object') return '';

  for (const kandidaat of [
    json.data,
    json.body,
    json.content,
    json.response,
    json.html
  ]) {
    if (
      typeof kandidaat === 'string' &&
      kandidaat.includes('<')
    ) {
      return kandidaat;
    }
  }

  return '';
}

function titelUitSlug(url = '') {
  const slug = String(url)
    .replace(/\/+$/, '')
    .split('/')
    .pop() || '';

  return decodeURIComponent(slug)
    .replace(/[-_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, teken => teken.toUpperCase());
}

const cfg = $('Code-Configuratie').first().json || {};
const medewerkers = Array.isArray(cfg.medewerkers)
  ? cfg.medewerkers
  : [];

const keywordMap = new Map();

for (const medewerker of medewerkers) {
  if (!medewerker || medewerker.actief === false) continue;

  const naam = String(medewerker.naam || '').trim();

  for (const keyword of (
    Array.isArray(medewerker.keywords)
      ? medewerker.keywords
      : []
  )) {
    const origineel = String(keyword || '').trim();
    const genormaliseerd = normaliseerTekst(origineel);

    if (!genormaliseerd) continue;

    if (!keywordMap.has(genormaliseerd)) {
      keywordMap.set(genormaliseerd, {
        keyword: origineel,
        medewerkers: new Set()
      });
    }

    if (naam) {
      keywordMap.get(genormaliseerd).medewerkers.add(naam);
    }
  }
}

const aanvragen = (() => {
  try {
    return $('Code-BlueTrail bouw zoekopdracht').all();
  } catch (e) {
    return [];
  }
})();

const gevonden = new Map();
const inputItems = $input.all();

for (let inputIndex = 0; inputIndex < inputItems.length; inputIndex++) {
  if (inputItems[inputIndex].json?.error) continue;
  const html = haalHtmlOp(inputItems[inputIndex].json);
  const meta = aanvragen[inputIndex]?.json || {};

  if (!html) continue;

  const linkRegex =
    /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;

  let match;

  while ((match = linkRegex.exec(html)) !== null) {
    const vacatureUrl = normaliseerUrl(match[1]);

    const detachering =
      /https?:\/\/(?:www\.)?bluetrail\.nl\/opdrachten\/detachering\/[^/]+\/?$/i
        .test(vacatureUrl);

    const interim =
      /https?:\/\/(?:www\.)?bluetrail\.nl\/opdrachten\/interim\/[^/]+\/?$/i
        .test(vacatureUrl);

    if (!detachering && !interim) continue;

    // Pak ruim omliggende kaarttekst. De kliktekst is vaak alleen
    // "Bekijk opdracht"; de functietitel en omschrijving staan ervoor.
    const start = Math.max(0, match.index - 1800);
    const einde = Math.min(
      html.length,
      linkRegex.lastIndex + 500
    );

    const contextHtml = html.slice(start, einde);
    const contextTekst = stripHtml(contextHtml);
    const contextNorm = normaliseerTekst(contextTekst);

    const gevondenKeywords = [];
    const keywordMedewerkers = new Set();

    for (const [genormaliseerd, informatie] of keywordMap.entries()) {
      if (!contextNorm.includes(genormaliseerd)) continue;

      gevondenKeywords.push(informatie.keyword);

      for (const naam of informatie.medewerkers) {
        keywordMedewerkers.add(naam);
      }
    }

    // De gebruiker heeft gevraagd om uitsluitend op medewerkerprofielen
    // te zoeken. Zonder keywordmatch wordt de vacature niet verwerkt.
    if (gevondenKeywords.length === 0) continue;

    const sleutel = vacatureUrl.toLowerCase();
    const dienstverband = detachering
      ? 'Detachering'
      : 'Interim';

    if (!gevonden.has(sleutel)) {
      let titelVoorlopig = stripHtml(match[2])
        .replace(/^Bekijk opdracht$/i, '')
        .replace(/\s*Bekijk opdracht\s*$/i, '')
        .trim();

      if (
        !titelVoorlopig ||
        /^(bekijk|reageer|lees meer)/i.test(titelVoorlopig)
      ) {
        titelVoorlopig = titelUitSlug(vacatureUrl);
      }

      gevonden.set(sleutel, {
        vacatureUrl,
        vacatureTitelVoorlopig: titelVoorlopig,
        blueTrailDienstverband: dienstverband,
        blueTrailGevondenKeywords: [],
        blueTrailKeywordMedewerkers: [],
        broker: meta.broker || 'BlueTrail',
        brokerEmail:
          meta.brokerEmail || 'info@bluetrail.nl',
        bronBerichtId: meta.bronBerichtId || '',
        bronBerichtOnderwerp:
          meta.bronBerichtOnderwerp || '',
        emailOntvangenOp: meta.emailOntvangenOp || ''
      });
    }

    const record = gevonden.get(sleutel);

    for (const keyword of gevondenKeywords) {
      if (!record.blueTrailGevondenKeywords.includes(keyword)) {
        record.blueTrailGevondenKeywords.push(keyword);
      }
    }

    for (const naam of keywordMedewerkers) {
      if (!record.blueTrailKeywordMedewerkers.includes(naam)) {
        record.blueTrailKeywordMedewerkers.push(naam);
      }
    }
  }
}

let resultaten = Array.from(gevonden.values());

const maximum = Math.max(
  1,
  Number(cfg.blueTrailMaxUniekeVacatures || 300)
);

if (
  cfg.testmodus &&
  Number(cfg.maximaalAantalVacatures) > 0
) {
  resultaten = resultaten.slice(
    0,
    Math.min(
      Number(cfg.maximaalAantalVacatures),
      maximum
    )
  );
} else {
  resultaten = resultaten.slice(0, maximum);
}

return resultaten.map(json => ({ json }));

// BlueTrail v1.7.3 detailparser
function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, c) =>
      String.fromCodePoint(Number(c))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, c) =>
      String.fromCodePoint(parseInt(c, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlNaarTekst(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<!--[\\s\\S]*?-->/g, ' ')
      .replace(/<(br|hr)\s*\/?>/gi, '\n')
      .replace(
        /<\/(p|div|section|article|li|h1|h2|h3|h4|tr)>/gi,
        '\n'
      )
      .replace(/<li\b[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function metaContent(html = '', naam = '') {
  const escaped = naam.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const patronen = [
    new RegExp(
      `<meta[^>]+(?:property|name)=["']${escaped}["'][^>]+content=["']([^"']+)["']`,
      'i'
    ),
    new RegExp(
      `<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${escaped}["']`,
      'i'
    )
  ];

  for (const patroon of patronen) {
    const match = html.match(patroon);
    if (match?.[1]) return decodeHtml(match[1]).trim();
  }

  return '';
}

function schoonTitel(value = '') {
  return decodeHtml(htmlNaarTekst(value))
    .replace(/\s*[-|]\s*BlueTrail.*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isGeneriekeTitel(value = '') {
  return /^(opdrachten via bluetrail|onze opdrachten|bluetrail|opdrachten)$/i
    .test(String(value).trim());
}

function haalTitel(html = '', fallback = '') {
  // H1 is de werkelijke functietitel op de vacaturedetailpagina.
  const h1Matches = [
    ...String(html).matchAll(
      /<h1\b[^>]*>([\s\S]*?)<\/h1>/gi
    )
  ];

  for (const match of h1Matches) {
    const waarde = schoonTitel(match[1]);

    if (waarde && !isGeneriekeTitel(waarde)) {
      return waarde;
    }
  }

  const og = schoonTitel(metaContent(html, 'og:title'));

  if (og && !isGeneriekeTitel(og)) {
    return og;
  }

  const titleMatch = String(html).match(
    /<title\b[^>]*>([\s\S]*?)<\/title>/i
  );
  const title = schoonTitel(titleMatch?.[1] || '');

  if (title && !isGeneriekeTitel(title)) {
    return title;
  }

  return schoonTitel(fallback);
}

function haalVacatureTekst(html = '') {
  const patronen = [
    /<main\b[^>]*>([\s\S]*?)<\/main>/i,
    /<article\b[^>]*>([\s\S]*?)<\/article>/i,
    /<div\b[^>]*class=["'][^"']*(?:vacancy|opdracht|job|single)[^"']*["'][^>]*>([\s\S]*?)<\/div>/i
  ];

  for (const patroon of patronen) {
    const match = String(html).match(patroon);
    const tekst = htmlNaarTekst(match?.[1] || '');

    if (tekst.length >= 100) return tekst;
  }

  return htmlNaarTekst(html);
}

function haalOpdrachtgever(tekst = '') {
  const patronen = [
    /(?:opdrachtgever|organisatie|klant)\s*[:\-]\s*([^\n|]{2,100})/i,
    /(?:voor|bij)\s+([A-ZÀ-Ý][^\n,.]{2,80})/i
  ];

  for (const patroon of patronen) {
    const match = String(tekst).match(patroon);

    if (match?.[1]) {
      return match[1]
        .replace(/\s+/g, ' ')
        .replace(/[.;,:]+$/g, '')
        .trim();
    }
  }

  return '';
}

const httpItems = $input.all();

let urlItems = [];
try {
