// Randstad Professional / Yacht v1.8.0
// Haalt unieke directe vacaturelinks uit één of meerdere Yacht-mails.
// Ondersteunt zowel HTML-links als Outlook-tekstweergave.

function decodeHtml(value = '') {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/=3D/gi, '=')
    .replace(/=\r?\n/g, '');
}

function normaliseerUrl(value = '') {
  let url = decodeHtml(value)
    .replace(/[)>.,;]+$/g, '')
    .trim();

  if (url.startsWith('//')) url = `https:${url}`;
  if (url.startsWith('http://')) {
    url = `https://${url.slice('http://'.length)}`;
  }

  try {
    const parsed = new URL(url);
    parsed.hash = '';

    // Trackingparameters zijn niet nodig voor het ophalen en dedupliceren.
    for (const key of [
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_content',
      'utm_term',
      'sc',
      'source'
    ]) {
      parsed.searchParams.delete(key);
    }

    return parsed.toString().replace(/\/$/, '');
  } catch (e) {
    return url.split('#')[0].split('?')[0].replace(/\/$/, '');
  }
}

const output = [];
const gezien = new Set();

const inputItems = $input.all();

for (let inputIndex = 0; inputIndex < inputItems.length; inputIndex++) {
