  const body =
    j.body?.content ??
    j.body?.Content ??
    j.body ??
    j.text ??
    j.content ??
    j.bodyPreview ??
    '';

  const bronTekst =
    typeof body === 'string'
      ? decodeHtml(body)
      : decodeHtml(JSON.stringify(body));

  const kandidaten = [];

  // HTML href-links.
  for (const match of bronTekst.matchAll(
    /href\s*=\s*["']([^"']*?(?:www\.)?yacht\.nl\/vacatures\/\d+[^"']*)["']/gi
  )) {
    kandidaten.push(match[1]);
  }

  // Platte tekst / Outlook-linkweergave.
  for (const match of bronTekst.matchAll(
    /https?:\/\/(?:www\.)?yacht\.nl\/vacatures\/\d+(?:[^\s"'<>)]*)?/gi
  )) {
    kandidaten.push(match[0]);
  }

  for (const kandidaat of kandidaten) {
    const vacatureUrl = normaliseerUrl(kandidaat);

    if (
      !/^https:\/\/(?:www\.)?yacht\.nl\/vacatures\/\d+/i.test(vacatureUrl)
    ) {
      continue;
    }

    const sleutel = vacatureUrl.toLowerCase();
    if (gezien.has(sleutel)) continue;
    gezien.add(sleutel);

    output.push({
      json: {
        vacatureUrl,
        broker: j.broker || 'Randstad Professional / Yacht',
        brokerEmail: j.brokerEmail || 'info@yacht.nl',
        bronCode: 'yacht',
        emailOntvangenOp:
          j.emailOntvangenOp ||
          j.receivedDateTime ||
          j.createdDateTime ||
          '',
        bronBerichtId:
          j.bronBerichtId ||
          j.id ||
          '',
