function zoekWaarde(tekst = '', patroon, groep = 1) {
  const match = String(tekst).match(patroon);
  return match?.[groep]
    ? String(match[groep]).replace(/\s+/g, ' ').trim()
    : '';
}

function veld(tekst = '', label = '') {
  const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return zoekWaarde(
    tekst,
    new RegExp(
      `(?:^|\\n)\\s*${escaped}\\s*:\\s*([^\\n]+)`,
      'i'
    )
  );
}

function knipTussen(tekst = '', startPatroon, eindePatronen = []) {
  let start = 0;
  const startMatch = String(tekst).match(startPatroon);

  if (startMatch?.index !== undefined) {
    start = startMatch.index;
  }

  let einde = tekst.length;

  for (const patroon of eindePatronen) {
    const deel = tekst.slice(start);
    const match = deel.match(patroon);

    if (
      match?.index !== undefined &&
      start + match.index < einde
    ) {
      einde = start + match.index;
    }
  }

  return tekst.slice(start, einde).trim();
}

function maakVacatureTekst(volledig = '') {
  // Samenvatting bovenaan behouden.
  const samenvattingStart =
    volledig.search(/(?:^|\n)\s*Aanvraagnummer\s*:/i);

  const functieprofielStart =
    volledig.search(/(?:^|\n)\s*Functieprofiel\s*(?:\n|$)/i);

  let samenvatting = '';
  let functieprofiel = '';

  if (samenvattingStart >= 0) {
    const samenvattingEinde =
      functieprofielStart > samenvattingStart
        ? functieprofielStart
        : volledig.length;

    samenvatting = volledig
      .slice(samenvattingStart, samenvattingEinde)
      // Verwijder vaste leveranciersinstructies tussen samenvatting
      // en Functieprofiel.
      .replace(
        /Deze aanvraag niet publiceren[\s\S]*?(?=Functieprofiel|$)/i,
        ''
      )
      .replace(
        /Klik op de link om de aanvraag[\s\S]*?(?=Functieprofiel|$)/i,
        ''
      )
      .replace(
        /Graag uitsluitend reageren[\s\S]*?(?=Functieprofiel|$)/i,
        ''
      )
      .replace(
        /Vier redenen om je kandidaat[\s\S]*?(?=Functieprofiel|$)/i,
        ''
      )
      .replace(
        /Vermeld bij kandidaten[\s\S]*?(?=Functieprofiel|$)/i,
        ''
      )
      .trim();
  }

  if (functieprofielStart >= 0) {
    functieprofiel = knipTussen(
      volledig.slice(functieprofielStart),
      /^/,
      [
        /(?:^|\n)\s*Na de sluitingsdatum krijg je\b/i,
        /(?:^|\n)\s*PS:\s*Wil je geen openstaande aanvragen\b/i,
        /(?:^|\n)\s*Met vriendelijke groet\b/i
      ]
    );
  }

  return normaliseerTekst(
    [samenvatting, functieprofiel]
      .filter(Boolean)
      .join('\n\n')
  );
}

