// MiPublic v1.10.0 detailparser

function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, c) =>
      String.fromCodePoint(Number(c))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, c) =>
      String.fromCodePoint(parseInt(c, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlNaarTekst(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(br|hr)\s*\/?>/gi, '\n')
      .replace(
        /<\/(p|div|section|article|li|h1|h2|h3|h4|tr|dt|dd)>/gi,
        '\n'
      )
      .replace(/<li\b[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function metaContent(html = '', naam = '') {
  const escaped = naam.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const patronen = [
    new RegExp(
      `<meta[^>]+(?:property|name)=["']${escaped}["'][^>]+content=["']([^"']+)["']`,
      'i'
    ),
    new RegExp(
      `<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${escaped}["']`,
      'i'
    )
  ];

  for (const patroon of patronen) {
    const match = String(html).match(patroon);
    if (match?.[1]) return decodeHtml(match[1]).trim();
  }

  return '';
}

function schoonTitel(value = '') {
  return htmlNaarTekst(value)
    .replace(/\s*[-|]\s*MiPublic.*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function haalTitel(html = '', fallback = '') {
  for (const match of String(html).matchAll(
    /<h1\b[^>]*>([\s\S]*?)<\/h1>/gi
  )) {
    const titel = schoonTitel(match[1]);
    if (titel && titel.length >= 3) return titel;
  }

  const og = schoonTitel(metaContent(html, 'og:title'));
  if (og) return og;

  const titleMatch = String(html).match(
    /<title\b[^>]*>([\s\S]*?)<\/title>/i
  );

  return schoonTitel(titleMatch?.[1] || fallback);
}

function haalVacatureTekst(html = '') {
  const patronen = [
    /<main\b[^>]*>([\s\S]*?)<\/main>/i,
    /<article\b[^>]*>([\s\S]*?)<\/article>/i,
    /<div\b[^>]*class=["'][^"']*(?:vacature|job|opdracht|single)[^"']*["'][^>]*>([\s\S]*?)<\/div>/i
  ];

  for (const patroon of patronen) {
    const match = String(html).match(patroon);
    const tekst = htmlNaarTekst(match?.[1] || '');

    if (tekst.length >= 200) return tekst;
  }

  return htmlNaarTekst(html);
}

function zoekVeld(tekst = '', labels = []) {
  for (const label of labels) {
    const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = String(tekst).match(
      new RegExp(
        `(?:^|\\n)\\s*${escaped}\\s*[:\\-]?\\s*([^\\n|]{2,120})`,
        'i'
      )
    );

    if (match?.[1]) {
      return match[1]
        .replace(/\s+/g, ' ')
        .replace(/[.;,:]+$/g, '')
        .trim();
    }
  }

  return '';
}

