function decodeHtml(value = '') {
  return String(value)
    .replace(/\\r\\n|\\n|\\r/g, '\n')
    .replace(/\\"/g, '"')
    .replace(/\\\//g, '/')
    .replace(/&#(\d+);/g, (_, c) =>
      String.fromCodePoint(Number(c))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, c) =>
      String.fromCodePoint(parseInt(c, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function stripHtml(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

function normaliseerUrl(value = '') {
  let url = decodeHtml(value).trim();

  if (url.startsWith('//')) {
    url = `https:${url}`;
  } else if (url.startsWith('/')) {
    url = `https://www.zzp-opdrachten.nl${url}`;
  }

  return url
    .split('#')[0]
    .split('?')[0]
    .replace(/\/$/, '');
}

function haalAjaxData(response = {}) {
  if (typeof response === 'string') {
    try {
      response = JSON.parse(response);
    } catch (e) {
      return response;
    }
  }

  if (typeof response?.data === 'string') {
    return response.data;
  }

  if (typeof response?.body === 'string') {
    try {
      const parsed = JSON.parse(response.body);
      return parsed?.data || response.body;
    } catch (e) {
      return response.body;
    }
  }

  return '';
}

