  )) {
    const origineel = String(keyword || '').trim();
    const sleutel = normaliseer(origineel);

    if (!sleutel) continue;

    if (!keywordMap.has(sleutel)) {
      keywordMap.set(sleutel, {
        keyword: origineel,
        medewerkers: new Set()
      });
    }

    if (naam) keywordMap.get(sleutel).medewerkers.add(naam);
  }
}

const meta = $('Code-FlexSpot overzicht').first().json || {};
const input = $input.first()?.json || {};
if (input.error) return [];

const html = htmlUit(input);
if (!html) return [];

const gevonden = new Map();
const linkRegex =
  /href\s*=\s*["']((?:https?:\/\/flexspot\.io)?\/opdrachten\/[^"'?#]+)["']/gi;

let match;

while ((match = linkRegex.exec(html)) !== null) {
  const vacatureUrl = normaliseerUrl(match[1]);

  if (!/^https:\/\/flexspot\.io\/opdrachten\//i.test(vacatureUrl)) continue;
  if (/\/opdrachten$/i.test(vacatureUrl)) continue;

  const start = Math.max(0, match.index - 2200);
  const einde = Math.min(html.length, linkRegex.lastIndex + 1400);
  const contextHtml = html.slice(start, einde);
  const contextTekst = stripHtml(contextHtml);
  const contextNorm = normaliseer(contextTekst);

  if (!contextNorm.includes('detachering')) continue;

  const gevondenKeywords = [];
  const relevanteMedewerkers = new Set();

  for (const [sleutel, info] of keywordMap.entries()) {
    if (!contextNorm.includes(sleutel)) continue;

    gevondenKeywords.push(info.keyword);
    for (const naam of info.medewerkers) relevanteMedewerkers.add(naam);
  }

  if (gevondenKeywords.length === 0) continue;

  const sleutel = vacatureUrl.toLowerCase();

  if (!gevonden.has(sleutel)) {
    const titelMatch =
      contextHtml.match(/<h[1-4]\b[^>]*>([\s\S]*?)<\/h[1-4]>/i) ||
      contextHtml.match(/class=["'][^"']*(?:title|functie|job|opdracht)[^"']*["'][^>]*>([\s\S]*?)<\//i);

    gevonden.set(sleutel, {
      vacatureUrl,
      vacatureTitelVoorlopig:
        stripHtml(titelMatch?.[1] || '') ||
        titelUitSlug(vacatureUrl),

      broker: meta.broker || 'FlexSpot',
      brokerEmail: meta.brokerEmail || 'info@flexspot.io',
      bronCode: 'flexspot',
      bronBerichtId: meta.bronBerichtId || '',
      bronBerichtOnderwerp: meta.bronBerichtOnderwerp || '',
      emailOntvangenOp: meta.emailOntvangenOp || '',

      flexspotDienstverband: 'Detachering',
      flexspotZoekwoorden: [],
      flexspotZoektermMedewerkers: []
    });
  }

  const record = gevonden.get(sleutel);

  for (const keyword of gevondenKeywords) {
    if (!record.flexspotZoekwoorden.includes(keyword)) {
      record.flexspotZoekwoorden.push(keyword);
    }
  }

  for (const naam of relevanteMedewerkers) {
    if (!record.flexspotZoektermMedewerkers.includes(naam)) {
      record.flexspotZoektermMedewerkers.push(naam);
    }
  }
}

return Array.from(gevonden.values())
  .slice(0, Number(cfg.flexspotMaxUniekeVacatures || 300))
  .map(json => ({ json }));

// FlexSpot v1.15.0
function decodeHtml(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'");
}

function htmlNaarTekst(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<(br|hr)\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|section|article|li|h1|h2|h3|h4)>/gi, '\n')
      .replace(/<li\b[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

let bronItems = [];
try { bronItems = $('Code-FlexSpot zoekresultaten').all(); } catch (e) {}

return $input.all().map((item, index) => {
  const httpData = item.json || {};
  const bron = bronItems[index]?.json || {};

  const html =
    typeof httpData.data === 'string' ? httpData.data :
    typeof httpData.body === 'string' ? httpData.body :
    typeof httpData.content === 'string' ? httpData.content :
    '';

  const h1 = html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);
  const vacatureTitel = htmlNaarTekst(
    h1?.[1] || bron.vacatureTitelVoorlopig || ''
  )
    .replace(/\s*\|\s*$/, '')
    .trim();

  const main =
    html.match(/<main\b[^>]*>([\s\S]*?)<\/main>/i) ||
    html.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i);

  const vacatureTekst = htmlNaarTekst(main?.[1] || html);

  const geldig =
    Boolean(vacatureTitel) &&
    vacatureTekst.length >= 200;

  return {
    json: {
      vacatureTitel,
      vacatureTekst,
      vacatureUrl: bron.vacatureUrl || '',
      broker: 'FlexSpot',
      brokerEmail: 'info@flexspot.io',
      bronCode: 'flexspot',
      dienstverband: 'Detachering',
      flexspotZoekwoorden: bron.flexspotZoekwoorden || [],
      flexspotZoektermMedewerkers:
        bron.flexspotZoektermMedewerkers || [],
      emailOntvangenOp: bron.emailOntvangenOp || '',
      bronBerichtId: bron.bronBerichtId || '',
      bronBerichtOnderwerp: bron.bronBerichtOnderwerp || '',
      flexspotDetailStatus: geldig ? 'verwerkt' : 'ongeldig',
      flexspotDetailFout:
        geldig ? '' : 'Geen bruikbare FlexSpot-detailpagina'
    },
    pairedItem: { item: index }
  };
});

const geldig = [];

for (const item of $input.all()) {
  const j = item.json || {};

  if (
    j.flexspotDetailStatus === 'verwerkt' &&
    String(j.vacatureTitel || '').trim() &&
    String(j.vacatureTekst || '').trim().length >= 200
  ) {
    geldig.push(item);
  }
}

return geldig;
